// Prepara los datos que envía la web del contrato y redacta el mensaje de WhatsApp
const entrada = $input.first().json;
const p = entrada.body || entrada;

// Teléfono: si viene sin prefijo internacional se le añade el 34
const digitos = String(p.telefono || '').replace(/[^0-9]/g, '');
const numero = digitos.length === 9 ? '34' + digitos : digitos;

const nombre = String(p.aceptante || p.empresa || '').trim() || 'cliente';

const texto = [
  'Hola ' + nombre + ':',
  '',
  'Hemos recibido tu contrato de arrendamiento de maquinaria nº ' + (p.numero_contrato || '') + ', con los datos que nos facilitaste en la web.',
  '',
  'Te lo enviamos también por correo a ' + (p.email || '') + '. Puedes descargarlo aquí:',
  p.pdf || '',
  '',
  'Imprímelo, fírmalo y devuélvenoslo respondiendo al correo o subiéndolo desde ese mismo enlace.',
  'Si necesitas cualquier cosa, respóndenos por aquí.',
  '',
  'Un saludo,',
  'Adara Excavaciones'
].join('\n');

return [{
  json: {
    numero: numero,
    texto: texto,
    tiene_telefono: numero.length >= 11,
    id: p.id || '',
    numero_contrato: p.numero_contrato || '',
    empresa: p.empresa || '',
    aceptante: p.aceptante || '',
    email: p.email || '',
    telefono: p.telefono || '',
    pdf: p.pdf || ''
  }
}];
